def hydrate_time(nanoseconds, tz=None):
    """
    Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: Number of nanoseconds since the Unix epoch (int, float, or convertible to int).
    :param tz: Optional timezone information. Can be a datetime.tzinfo instance or a string name understood by zoneinfo.
    :return: datetime.time object. If tz is provided, the returned time will be timezone-aware; otherwise it will be naive.
    """
    # Return None if no value provided
    if nanoseconds is None:
        return None

    # Import required modules locally to avoid top-level imports
    try:
        import datetime
    except Exception as exc:
        raise RuntimeError("datetime module is required") from exc

    # Validate and convert nanoseconds to integer
    try:
        ns_int = int(nanoseconds)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"nanoseconds must be an integer number of nanoseconds, got {nanoseconds!r}") from exc

    # Convert nanoseconds to seconds
    seconds = ns_int / 1_000_000_000

    # Create a UTC datetime from the timestamp
    try:
        base_dt = datetime.datetime.utcfromtimestamp(seconds).replace(tzinfo=datetime.timezone.utc)
    except Exception as exc:
        raise ValueError(f"Invalid nanoseconds value: {nanoseconds!r}") from exc

    # Handle timezone conversion if tz is provided
    if tz is not None:
        if isinstance(tz, datetime.tzinfo):
            tzinfo = tz
        else:
            # Try to interpret tz as a zoneinfo name
            try:
                from zoneinfo import ZoneInfo  # Python 3.9+
                tzinfo = ZoneInfo(tz)
            except Exception as exc:
                raise ValueError(f"Invalid timezone specification: {tz!r}") from exc
        base_dt = base_dt.astimezone(tzinfo)

    # Return time component
    if tz is None:
        # Return naive time
        return base_dt.time()
    else:
        # Return timezone-aware time
        return base_dt.timetz()

