def dehydrate_point(value):
    """Dehydrator for Point data.

    :param value: Point-like object
    :type value: object
    :return: Dictionary with 'x' and 'y' coordinates or None
    """
    # Handle None explicitly
    if value is None:
        return None

    # If the value is a sequence (tuple/list) of two items, assume coordinates
    if isinstance(value, (tuple, list)):
        if len(value) == 2:
            return {"x": value[0], "y": value[1]}

    # Try to pull out attributes typically used for points
    try:
        x = getattr(value, "x")
        y = getattr(value, "y")
    except AttributeError:
        # Try common alternatives (e.g., point.x, point.y as properties)
        try:
            x = getattr(value, "x", None)
            y = getattr(value, "y", None)
        except Exception:
            pass

    # If we successfully retrieved coordinates, return them
    if isinstance(x, (int, float)) and isinstance(y, (int, float)):
        return {"x": x, "y": y}

    # If it doesn't match any known format, raise a helpful error
    raise TypeError(
        f"Unsupported type for dehydrate_point: {type(value).__name__}"
    )

