def unit_of_work(metadata=None, timeout=None):
    """
    Decorator that sets transaction metadata and timeout on the transaction object
    passed to the decorated function before execution.
    """
    # Validate metadata
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError("metadata must be a dict or None")

    # Validate timeout
    if timeout is not None:
        if not isinstance(timeout, (int, float)):
            raise TypeError("timeout must be a number or None")
        if timeout < 0:
            raise ValueError("timeout must be zero or positive")

    def decorator(func):
        from functools import wraps

        @wraps(func)
        def wrapper(*args, **kwargs):
            # Retrieve the transaction object (`tx`) from args or kwargs
            tx = None
            if args:
                tx = args[0]
            if tx is None:
                tx = kwargs.get("tx")
            if tx is None:
                raise ValueError("Transaction object 'tx' not provided to the decorated function")

            # Apply metadata if the transaction supports it
            if metadata is not None:
                set_meta = getattr(tx, "set_metadata", None) or getattr(tx, "set_meta_data", None)
                if callable(set_meta):
                    try:
                        set_meta(metadata)
                    except Exception as e:
                        raise RuntimeError(f"Failed to set metadata on transaction: {e}") from e

            # Apply timeout if the transaction supports it
            if timeout is not None:
                set_tmo = getattr(tx, "set_timeout", None)
                if callable(set_tmo):
                    try:
                        set_tmo(timeout)
                    except Exception as e:
                        raise RuntimeError(f"Failed to set timeout on transaction: {e}") from e

            # Execute the original function with the transaction
            return func(*args, **kwargs)

        return wrapper

    return decorator

