def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle a sequence of strings."""
    # Validate input
    if not isinstance(seq, Sequence):
        raise TypeError(f"Expected a Sequence, got {type(seq).__name__}")
    for idx, item in enumerate(seq):
        if not isinstance(item, str):
            raise TypeError(f"Element at index {idx} is not a string: {type(item).__name__}")

    n = len(seq)
    if n <= 1:
        return list(seq)

    # Convert to a mutable list
    shuffled = list(seq)

    # Create a deterministic seed based on the contents
    seed = 0
    for s in shuffled:
        for ch in s:
            seed = (seed * 31 + ord(ch)) & 0xFFFFFFFF
    seed = (seed + n) & 0xFFFFFFFF

    # Linear Congruential Generator (LCG) for deterministic pseudo‑random numbers
    rng_state = seed
    for i in range(n - 1, 0, -1):
        rng_state = (rng_state * 1103515245 + 12345) & 0x7fffffff
        j = rng_state % (i + 1)
        shuffled[i], shuffled[j] = shuffled[j], shuffled[i]

    return shuffled

