def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    import sys

    # Basic validation
    if not isinstance(cmd, tuple):
        raise TypeError("cmd must be a tuple")
    if len(cmd) == 0:
        return cmd
    for arg in cmd:
        if not isinstance(arg, str):
            raise TypeError("all elements of cmd must be str")

    # If not on Windows, nothing to fix
    if not sys.platform.startswith("win"):
        return cmd

    # Ensure that command arguments are correctly quoted if they contain spaces.
    def quote_if_needed(arg: str) -> str:
        if " " in arg or "\t" in arg:
            return f'"{arg}"'
        return arg

    # If the first argument is a script which has a shebang that refers to an
    # interpreter without the .exe extension, we need to adjust it so that the
    # interpreter is runnable on Windows. Windows requires the `.exe` suffix for
    # executables.
    first = cmd[0]
    # If the first argument already points to an executable we leave it untouched
    if any(first.lower().endswith(ext) for ext in (".exe", ".bat", ".cmd", ".com")):
        return tuple(quote_if_needed(a) for a in cmd)

    # Otherwise try to open the file and inspect its shebang.
    try:
        with open(first, "rb") as f:
            first_line = f.readline()
    except Exception:
        first_line = b""

    if first_line.startswith(b"#!"):
        # Parse the shebang line. Note that it may contain comments after the path.
        # The interpreter path is the first token after "#!".
        shebang = first_line[2:].strip().split()
        if not shebang:
            return tuple(quote_if_needed(a) for a in cmd)

        interp = shebang[0]
        # The path may be relative to the location of the script.
        if not os.path.isabs(interp):
            script_dir = os.path.dirname(os.path.abspath(first))
            interp = os.path.normpath(os.path.join(script_dir, interp))

        # If the interpreter path lacks an executable extension, try to add .exe
        if not any(interp.lower().endswith(e) for e in (".exe", ".bat", ".cmd", ".com")):
            # On Windows the interpreter may be a Python executable
            # Try appending ".exe" and ".bat" if they exist.
            for suffix in (".exe", ".bat", ".cmd", ".com"):
                candidate = interp + suffix
                if os.path.exists(candidate):
                    interp = candidate
                    break
            else:
                # If no suitable executable found, fallback to sys.executable
                interp = sys.executable

        # Assemble new command tuple: interpreter followed by script and remaining args
        new_cmd = (interp,) + (first,) + cmd[1:]
        return tuple(quote_if_needed(a) for a in new_cmd)

    # No shebang or nothing to adjust, just quote for spaces
    return tuple(quote_if_needed(a) for a in cmd)

