def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    Parameters
    ----------
    cache : dict-like
        Mapping to store computed results.
    key : callable, optional
        Function that accepts the wrapped function's arguments and returns a
        hashable key for the cache. Defaults to ``hashkey``.
    lock : context manager or lock-like, optional
        Optional lock to use around cache access for thread safety.

    Returns
    -------
    decorator : callable
        Wrapper decorator.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Compute cache key
            try:
                k = key(*args, **kwargs)
            except Exception:
                # Fallback key that uses string representations to guarantee
                # hashability even if original arguments are unhashable.
                k = (repr(args), frozenset((k, repr(v)) for k, v in kwargs.items()))
            # Acquire lock if provided
            if lock:
                if hasattr(lock, "__enter__") and hasattr(lock, "__exit__"):
                    lock_context = lock
                else:
                    # Assume standard lock with acquire/release
                    lock.acquire()
                    lock_context = None
                try:
                    if lock_context:
                        with lock_context:
                            return _lookup_or_compute(k)
                    else:
                        return _lookup_or_compute(k)
                finally:
                    if lock_context is None:
                        lock.release()
            else:
                return _lookup_or_compute(k)

        def _lookup_or_compute(k):
            if k in cache:
                return cache[k]
            result = func(*args, **kwargs)
            cache[k] = result
            return result

        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper

    return decorator

