    def _reset_logging(cls):
        """
        Reset logging configuration to a clean state by removing all handlers
        from the root logger and resetting its level to NOTSET. This allows
        logging.basicConfig() to be called again without errors.
        """
        import logging
        try:
            root_logger = logging.getLogger()
            # Remove all handlers from the root logger
            for handler in root_logger.handlers[:]:
                try:
                    root_logger.removeHandler(handler)
                    handler.close()
                except Exception:
                    # Ignore any error closing handlers
                    pass
            # Reset the logger level to NOTSET (inherit)
            root_logger.setLevel(logging.NOTSET)
        except Exception as exc:
            # Fail quietly: log an error message to stderr if possible
            try:
                import sys
                sys.stderr.write(f"Error resetting logging: {exc}\n")
            except Exception:
                # If even this fails, give up silently
                pass"

