def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.
    """
    from collections import defaultdict, deque

    # Track all unique items and their first appearance index
    appearance = {}
    element_set = set()
    for seq_idx, seq in enumerate(orderings):
        for pos, item in enumerate(seq):
            if item not in appearance:
                appearance[item] = (seq_idx, pos)
            element_set.add(item)

    # Build graph with edges only between consecutive items in each ordering
    adjacency = defaultdict(set)
    indegree = defaultdict(int)
    for seq in orderings:
        for i in range(len(seq) - 1):
            u, v = seq[i], seq[i + 1]
            if v not in adjacency[u]:
                adjacency[u].add(v)
                indegree[v] += 1

    # Ensure all elements have an indegree entry
    for item in element_set:
        indegree.setdefault(item, 0)

    # Prepare queue of nodes with indegree 0, sorted by appearance
    zero_indeg = deque(sorted(
        (item for item in element_set if indegree[item] == 0),
        key=lambda x: appearance[x]
    ))

    result = []
    visited_count = 0
    while zero_indeg:
        current = zero_indeg.popleft()
        result.append(current)
        visited_count += 1
        for neighbor in adjacency[current]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                # Insert neighbor keeping appearance order among zero indegree nodes
                inserted = False
                for idx, node in enumerate(zero_indeg):
                    if appearance[neighbor] < appearance[node]:
                        zero_indeg.insert(idx, neighbor)
                        inserted = True
                        break
                if not inserted:
                    zero_indeg.append(neighbor)

    if visited_count != len(element_set):
        raise ValueError("Orderings contain a cycle or inconsistent constraints")

    return result

