def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    try:
        from zope.interface import ProvidedBy
    except Exception as exc:
        raise ValueError(
            "zope.interface is required for retrieving directly provided interfaces"
        ) from exc
    # Get the registry object that keeps track of interface registrations for this object
    registry = ProvidedBy(object)
    # Most Zoo.pc/zope.interface implementations expose the directlyProvided
    # attribute (an IDeclaration) which contains exactly the interfaces
    # explicitly registered for this object.
    try:
        return registry.directlyProvided
    except AttributeError:
        # Fallback: if the object itself stores provides in a "__provides__" attribute
        if hasattr(object, "__provides__"):
            provides = getattr(object, "__provides__")
            try:
                return tuple(provides)
            except TypeError:
                pass
        # If we cannot determine directly provided interfaces, return empty
        return tuple()

