def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, list):
        raise TypeError("Expected a list of classes")
    minimal = []
    for i, cls in enumerate(classes):
        if not isinstance(cls, type):
            raise TypeError(f"Element at index {i} is not a class")
        # Skip if this class is already a subclass of any minimal class
        if any(issubclass(cls, base) for base in minimal):
            continue
        # Remove any existing minimal class that is a subclass of the new one
        minimal = [base for base in minimal if not issubclass(base, cls)]
        minimal.append(cls)
    return minimal

