def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if sequence is None:
        return tuple() if output is None else output
    # If output is not provided, create a fresh list for accumulation
    if output is None:
        output = []
    # Treat strings and bytes as indivisible items
    if isinstance(sequence, (str, bytes)):
        output.append(sequence)
        return tuple(output)
    # Ensure the input is iterable; if not, treat it as a single item
    try:
        iterator = iter(sequence)
    except TypeError:
        output.append(sequence)
        return tuple(output)
    for decl in iterator:
        if decl is None:
            # Skip None values silently
