def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    lines = []

    # Header handling
    if header is not None:
        if not isinstance(header, str):
            raise TypeError("header must be a string")
        lines.append(header)

    # Get iterable of points from the graph
    points = getattr(self, "points", None)
    if points is None:
        # maybe the graph itself is iterable
        if hasattr(self, "__iter__"):
            points = self
        else:
            # try a common fallback attribute
            points = getattr(self, "items", None)
            if points is None:
                raise AttributeError("Graph has no iterable 'points' or 'items'")

    # Helper to flatten an iterable into list of string representations
    def _flatten(obj):
        if obj is None:
            return []
        if isinstance(obj, str):
            return [obj]
        try:
            iter(obj)
        except Exception:
            return [str(obj)]
        else:
            return [str(x) for x in obj]

    for point in points:
        # Expected format: (coordinate, value) or just coordinate
        try:
            coord, value = point
        except Exception:
            coord = point
            value = None

        parts = _flatten(coord) + _flatten(value)
        # If the point had just a coordinate without value but coordinate was
        # a single non-iterable, _flatten(coord) would produce [str(coord)]
        # So we simply join all parts
        line = separator.join(parts)
        lines.append(line)

    return "\n".join(lines)

