def _update_context(self, context):
        """
        Update *context* with the properties of this graph.

        *context.error* is appended with indices of errors.
        Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
        Note that error names are called "x", "y" and "z"
        (this corresponds to first three coordinates,
        if they are present), which allows to simplify plotting.
        Existing values are not removed
        from *context.value* and its subcontexts.

        Called on "destruction" of the graph (for example,
        in :class:`.ToCSV`). By destruction we mean conversion
        to another structure (like text) in the flow.
        The graph object is not really destroyed in this process.
        """
        # Ensure context has the expected attributes
        if not hasattr(context, "error"):
            context.error = {}
        if not hasattr(context, "value"):
            context.value = {}

        # Helper: fetch the list of primary fields (non error fields)
        primary_fields = []
        try:
            # Most graph implementations expose `fields` or `field_names`
            if hasattr(self, "fields"):
                primary_fields = list(self.fields)
            elif hasattr(self, "field_names"):
                primary_fields = list(self.field_names)
            else:
                # Fallback: use all attribute names that do not start with 'error_'
                primary_fields = [
                    name for name in vars(self)
                    if not name.startswith("error_")
                ]
        except Exception:
            primary_fields = []

        # Map the first three primary fields to coordinates x, y, z
        coord_map = {}
        coord_names = ("x", "y", "z")
        for idx, name in enumerate(primary_fields[:3]):
            coord_map[name] = coord_names[idx]

        # Process each error attribute
        for attr_name in vars(self):
            if not attr_name.startswith("error_"):
                continue

            # Parse the error attribute name
            # Expected patterns: error_<field>_<suffix>
            parts = attr_name.split("_", 2)
            if len(parts) < 3:
                continue  # cannot parse
            base_field, suffix = parts[1], parts[2]

            # Determine coordinate key (x, y, z if applicable)
            coord_key = coord_map.get(base_field, base_field)

            # Construct error name as used in the context (e.g., 'x_low')
            error_key = f"{coord_key}_{suffix}"

            # Retrieve the error data; it could be a list/array or None
            error_data = getattr(self, attr_name, None)

            # Compute indices where error is non-empty/non-zero if possible
            indices = []
            if error_data is not None:
                try:
                    # If error_data is a sequence of numeric values
                    for i, val in enumerate(error_data):
                        if val is not None and val != 0:
                            indices.append(i)
                except Exception:
                    # If we cannot iterate, skip computation
                    indices = []

            # Append or merge into context.error
            # Preserve existing subcontexts if any
            existing = context.error.get(error_key)
            if existing is None:
                context.error[error_key] = {"index": indices}
            else:
                # Merge the indices safely
                if "index" in existing and isinstance(existing["index"], list):
                    existing["index"].extend(indices)
                else:
                    existing["index"] = indices

        # Note: The function does not modify context.value as per the
        # specification that existing values are not removed. If
        # additional value updates are required, they should be handled
        # elsewhere in the codebase. The function returns None implicitly.

