def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic validation
    if bins is None or edges is None:
        raise ValueError("Both bins and edges must be provided.")
    try:
        nbins = len(bins)
    except TypeError:
        raise TypeError("bins must be an array-like sequence.")
    try:
        ne = len(edges)
    except TypeError:
        raise TypeError("edges must be an array-like sequence.")
    if ne != nbins + 1:
        raise ValueError(f"Number of edges must be one more than number of bins: {ne} vs {nbins+1}.")
    # Compute widths and check ordering
    widths = []
    for i in range(nbins):
        try:
            width = edges[i + 1] - edges[i]
        except Exception as exc:
            raise TypeError("edges elements must support subtraction.") from exc
        if width <= 0:
            raise ValueError(f"Edge difference at index {i} is non-positive: {edges[i]} -> {edges[i+1]}.")
        widths.append(width)
    # Compute weighted sum
    total = 0.0
    for bin_val, width in zip(bins, widths):
        try:
            total += bin_val * width
        except Exception as exc:
            raise TypeError("bins elements must support multiplication and addition.") from exc
    return total

