        n_bins = len(bins)
    except TypeError:
        raise ValueError("bins must be a sequence with length attribute")
    if n_bins != n_edges - 1:
        raise ValueError(f"bins length ({n_bins}) must equal len(edges)-1 ({n_edges-1})")

    # Compute widths and integral
    total = 0.0
    for i in range(n_edges - 1):
