    def _diff(sub1, sub2, lvl):
        result = {}
        for key, val in sub1.items():
            if key not in sub2:
                # key absent in sub2, include it
                result[key] = val
                continue

            val2 = sub2[key]

            # If both are dicts and we have depth to recurse
            if isinstance(val, dict) and isinstance(val2, dict):
                if lvl == 0:
                    # depth exhausted, difference is whole subdict
                    result[key] = val
                    continue
                # recurse with reduced depth; -1 means infinite
                next_lvl = lvl - 1 if lvl > 0 else lvl
                nested = _diff(val, val2, next_lvl)
                if nested:
                    result[key] = nested
                # if nested empty, skip
            else:
                # Not both dicts - include if values differ
                if val != val2:
                    result[key] = val
        return result

