    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate weight
    try:
        weight_val = float(weight)
    except Exception:
        raise TypeError("weight must be a numeric value")

    # Determine edges attribute
    try:
        edges = self.edges
    except AttributeError:
        try:
            edges = self._edges
        except AttributeError:
            raise AttributeError("Histogram object has no 'edges' or '_edges' attribute")

    # Determine data array attribute
    try:
        data = self.data
    except AttributeError:
        try:
            data = self._data
        except AttributeError:
            try:
                data = self._bins
            except AttributeError:
                raise AttributeError("Histogram object has no array to store bin counts")

    # Convert coord to tuple for indexing
    if isinstance(coord, (int, float, np.number)):
        coord_seq = (coord,)
    else:
        try:
            coord_seq = tuple(coord)
        except Exception:
            raise TypeError("coord must be a numeric or iterable of numerics")

    # Check dimensionality
    if len(coord_seq) != len(edges):
        raise ValueError(f"Coordinate dimensionality {len(coord_seq)} does not match histogram dimensions {len(edges)}")

    # Find bin indices for each dimension
    indices = []
    for c, edge in zip(coord_seq, edges):
        # Use np.searchsorted to locate the bin
        idx = np.searchsorted(edge, c, side='right') - 1
        # If outside valid range, ignore the fill
        if idx < 0 or idx >= len(edge) - 1:
            return  # ignore out-of-range coordinate
        indices.append(idx)

    # Increment the count for the computed bin
    try:
        data[tuple(indices)] += weight_val
    except Exception as exc:
