def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    import re

    # Ensure the value is a string
    if not isinstance(value, str):
        raise ValidationError("Value must be a string")

    # Retrieve the validation regex from the global context
    pattern = globals().get("VALIDATION_REGEX")
    if pattern is None:
        raise ValidationError("No validation regex specified")

    try:
        # Compile if the pattern is provided as a string
        if isinstance(pattern, str):
            pattern = re.compile(pattern)
        # Use fullmatch to ensure the entire string satisfies the regex
        if not isinstance(pattern, re.Pattern) and hasattr(pattern, "fullmatch"):
            # For older Python versions where re.Pattern may not exist
            if not pattern.fullmatch(value):
                raise ValidationError(f"Value '{value}' does not match pattern {pattern}")
        elif not pattern.fullmatch(value):
            raise ValidationError(f"Value '{value}' does not match pattern {pattern.pattern}")
    except re.error as e:
        raise ValidationError(f"Invalid regex pattern: {e}") from e
    return None

