def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    if not isinstance(folder, str):
        raise TypeError("folder must be a string path")

    if not os.path.isdir(folder):
        raise ValueError(f"'{folder}' is not a valid directory")

    base_to_files = {}
    try:
        for entry in os.listdir(folder):
            full_path = os.path.join(folder, entry)
            if os.path.isfile(full_path):
                base, _ = os.path.splitext(entry)
                base_to_files.setdefault(base, []).append(full_path)
    except Exception as err:
        raise RuntimeError(f"Failed to list files in directory '{folder}': {err}") from err

    # Keep only those groups that have at least one XML file
    result = {}
    for base, files in base_to_files.items():
        if any(f.lower().endswith(".xml") for f in files):
            result[base] = files

    return result

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    data = {}
    try:
        for name in os.listdir(folder):
            full_path = os.path.join(folder, name)
            if not os.path.isfile(full_path):
                continue
            base, ext = os.path.splitext(name)
            if not base:
                continue
            ext = ext.lstrip(".").lower()
            if base not in data:
                data[base] = {}
            data[base][ext] = full_path
    except Exception:
        # If the folder does not exist, cannot read, or any I/O error,
        # return an empty dictionary rather than raising.
        return {}
    return data

