def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path

    Returns
    -------
    dict
        A dictionary where each key is the basename (without extension) of an XML file
        inside the zip, and the value is another dictionary mapping the relative file
        path within the zip to its raw bytes content.
    """
    # Validate input type
    if not isinstance(zip_path, str):
        raise TypeError(f"zip_path must be a string, got {type(zip_path)!r}")

    # Check if the file exists
    try:
        import os
        if not os.path.isfile(zip_path):
            raise FileNotFoundError(f"No such file: '{zip_path}'")
    except Exception as exc:
        raise exc

    packages = {}
    try:
        import zipfile
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for info in zf.infolist():
                # Skip directories
                if info.is_dir():
                    continue
                # Read byte content
                try:
                    data = zf.read(info)
                except RuntimeError:
                    # Skip files that cannot be read
                    continue
                # Determine if this file is an XML file and get its basename
                base, ext = os.path.splitext(os.path.basename(info.filename))
                if ext.lower() == '.xml':
                    # Ensure the key exists
                    if base not in packages:
                        packages[base] = {}
                    # Use the relative path within the zip as the key in value dict
                    packages[base][info.filename] = data
                else:
                    # For non-XML files, associate them with their XML counterpart if present
                    # Find which XML basename they might belong to:
                    # Check if any basename matches the file's stem
                    file_stem, _ = os.path.splitext(os.path.basename(info.filename))
                    if file_stem in packages:
                        packages[file_stem][info.filename] = data
                    else:
                        # If no corresponding XML, they will be ignored
                        pass
    except zipfile.BadZipFile:
        raise zipfile.BadZipFile(f"File '{zip_path}' is not a valid zip file")
    except Exception as exc:
        # General exception handling for unforeseen issues
        raise RuntimeError(f"Error processing zip file '{zip_path}': {exc}") from exc

    return packages

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        Mapping from XML basename to a dictionary of file paths and their decoded contents.
    """
    # Validate input
    if not isinstance(zip_path, str):
        raise TypeError(f"zip_path must be a string, got {type(zip_path).__name__}")

    try:
        import os
        import zipfile
    except ImportError as exc:
        raise RuntimeError("Required standard library modules not available") from exc

    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as z:
            for info in z.infolist():
                # Skip directories
                if info.is_dir():
                    continue

                file_path = info.filename
                base_name, ext = os.path.splitext(os.path.basename(file_path))
                # Only consider XML files as grouping key
                if ext.lower() != '.xml':
                    continue

                # Read file content, try to decode as UTF-8, fall back to latin-1 if necessary
                try:
                    raw_bytes = z.read(info)
                except KeyError:
                    # File not found in zip after listing; skip
                    continue
                try:
                    content = raw_bytes.decode('utf-8', errors='strict')
                except UnicodeDecodeError:
                    content = raw_bytes.decode('latin-1', errors='replace')

                group = result.setdefault(base_name, {})
                group[file_path] = content
    except FileNotFoundError as e:
        raise FileNotFoundError(f"Zip file not found: {zip_path}") from e
    except zipfile.BadZipFile as e:
        raise zipfile.BadZipFile(f"File is not a zip file or it is corrupted: {zip_path}") from e
    except Exception as e:
        # Catch-all for unexpected errors; re-raise with context
        raise RuntimeError(f"Failed to read zip file '{zip_path}': {e}") from e

    return result

