def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.

    Returns:
        tuple: (number, suppl) where
            - number is an int if a numeric issue number is found, otherwise None,
            - suppl is an int if a supplement number is found, otherwise None.
    """
    # Coerce to string
    try:
        text = str(issue).strip()
    except Exception:
        return (None, None)

    # If contains XML tags, strip them
    if text.lower().startswith("<issue") and ">" in text:
        # simple tag strip
        try:
            start = text.find(">")
            end = text.rfind("</")
            if start != -1 and end != -1:
                text = text[start + 1:end].strip()
        except Exception:
            pass

    if not text:
        return (None, None)

    # Regular expression patterns
    import re
    # Find the first integer as a candidate for the issue number
    number_match = re.search(r'\b(\d+)\b', text)
    number = int(number_match.group(1)) if number_match else None

    # Find a supplement number after a keyword
    # Keywords: sup, suppl, s, spe, supp
    suppl_match = re.search(
        r'(?:suppl|sup|s[.]?|spe|supp)[:\s]*\.?[\s]*\b(\d+)\b',
        text,
        flags=re.IGNORECASE,
    )
    suppl = int(suppl_match.group(1)) if suppl_match else None

    # Handle cases where no number but a supplement number is present
    # Example: "Suppl 12" -> number None, suppl 12
    # In that case, ensure number remains None
    if number is None and suppl_match:
        # Keep number as None
        pass

    # If a sup keyword is present but no supplement number, consider suppl as 0
    if re.search(r'(?:suppl|sup|s[.]?|spe|supp)\b', text, flags=re.IGNORECASE) and suppl is None:
        suppl = 0

    return (number, suppl)

def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    # Basic validation
    try:
        if issue is None:
            return (None, False)
        # If 'issue' is an XML element, get its text
        if hasattr(issue, "text"):
            content = issue.text
        else:
            content = str(issue)

        if not content:
            return (None, False)

        txt = content.strip()
        # Search for the first number (handles ranges like "2-5")
        number_match = re.search(r"\d+", txt)
        number = int(number_match.group()) if number_match else None

        # Define common supplement indicators (case-insensitive)
        supl_patterns = [
            r"\bsuppl\b",
            r"\bsupl\b",
            r"\bspe\b",
            r"\bsupp\b",
            r"\bs\b",
            r"\bpr\b",
        ]
        suppl_present = False
        for pat in supl_patterns:
            if re.search(pat, txt, flags=re.IGNORECASE):
                suppl_present = True
                break

        return (number, suppl_present)
    except Exception:
        # On unexpected errors, safely return defaults
        return (None, False)

