def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    visited = set()

    def _pretty(obj, level):
        sty = '    ' * level

        # Avoid infinite recursion for self-referential objects
        obj_id = id(obj)
        if obj_id in visited:
            return sty + '<recursive>'
        visited.add(obj_id)

        # Primitive types
        if isinstance(obj, (str, int, float, bool, type(None))):
            if debug:
                return sty + f'{type(obj).__name__}: {repr(obj)}'
            return sty + repr(obj)

        # Dictionaries
        if isinstance(obj, dict):
            if debug:
                header = sty + f'dict // {len(obj)} items {{'
                footer = sty + '}'
            else:
                header = sty + '{'
                footer = sty + '}'
            lines = [header]
            for key in sorted(obj.keys(), key=lambda k: str(k)):
                key_repr = repr(key)
                val_repr = _pretty(obj[key], level + 1)
                lines.append(f'{sty}    {key_repr}: {val_repr.strip()}')
            lines.append(footer)
            return '\n'.join(lines)

        # Lists and tuples
        if isinstance(obj, (list, tuple)):
            open_char = '[' if isinstance(obj, list) else '('
            close_char = ']' if isinstance(obj, list) else ')'
            if debug:
                header = sty + f'{type(obj).__name__} // {len(obj)} items {open_char}'
                footer = sty + close_char
            else:
                header = sty + open_char
                footer = sty + close_char
            lines = [header]
            for item in obj:
                item_repr = _pretty(item, level + 1)
                lines.append(f'{sty}    {item_repr.strip()}')
            lines.append(footer)
            return '\n'.join(lines)

        # Sets
        if isinstance(obj, set):
            if not obj:
                return sty + 'set()'
            if debug:
                header = sty + f'set // {len(obj)} items set(['
                footer = sty + '])'
            else:
                header = sty + 'set(['
                footer = sty + '])'
            lines = [header]
            for item in sorted(obj, key=lambda k: str(k)):
                item_repr = _pretty(item, level + 1)
                lines.append(f'{sty}    {item_repr.strip()}')
            lines.append(footer)
            return '\n'.join(lines)

        # Generic objects with __dict__
        try:
            attrs = vars(obj)
        except TypeError:
            attrs = None

        if attrs is not None:
            if debug:
                header = sty + f'{obj.__class__.__name__} // {len(attrs)} attrs ('
                footer = sty + ')'
            else:
                header = sty + f'{obj.__class__.__name__}('
                footer = sty + ')'
            lines = [header]
            for key in sorted(attrs.keys()):
                val_repr = _pretty(attrs[key], level + 1)
                lines.append(f'{sty}    {key}={val_repr.strip()}')
            lines.append(footer)
            return '\n'.join(lines)

        # Fallback representation
        if debug:
            return sty + f'{type(obj).__name__}: {repr(obj)}'
        return sty + repr(obj)

    return _pretty(self, indent)

def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        """
        visited = set()

        def _pretty(obj, level):
            # Avoid infinite recursion due to cyclic references
            if id(obj) in visited:
                return '...'
            visited.add(id(obj))

            prefix = ' ' * level

            # Primitive types: use repr directly
            if isinstance(obj, (str, int, float, bool, type(None))):
                return repr(obj)

            # Dictionaries
            if isinstance(obj, dict):
                if not obj:
                    return '{}'
                items = []
                for k, v in obj.items():
                    key_str = _pretty(k, level + 2)
                    val_str = _pretty(v, level + 2)
                    items.append(f"{key_str}: {val_str}")
                inner = ',\n'.join(' ' * (level + 2) + item for item in items)
                return '{\n' + inner + '\n' + prefix + '}'

            # Lists
            if isinstance(obj, list):
                if not obj:
                    return '[]'
                inner = ',\n'.join(' ' * (level + 2) + _pretty(v, level + 2) for v in obj)
                return '[\n' + inner + '\n' + prefix + ']'

            # Tuples
            if isinstance(obj, tuple):
                if not obj:
                    return '()'
                inner = ',\n'.join(' ' * (level + 2) + _pretty(v, level + 2) for v in obj)
                return '(\n' + inner + '\n' + prefix + ')'

            # Sets
            if isinstance(obj, set):
                if not obj:
                    return 'set()'
                inner = ',\n'.join(' ' * (level + 2) + _pretty(v, level + 2) for v in obj)
                return '{\n' + inner + '\n' + prefix + '}'

            # Objects with __dict__ or __slots__
            attrs = {}
            if hasattr(obj, "__dict__"):
                attrs.update(obj.__dict__)
            # Support __slots__ if defined
            slots = getattr(obj, "__slots__", None)
            if slots:
                if isinstance(slots, str):
                    slots = [slots]
                for slot in slots:
                    if hasattr(obj, slot):
                        attrs[slot] = getattr(obj, slot)

            if attrs:
                inner_items = []
                for k, v in attrs.items():
                    key_str = repr(k)
                    val_str = _pretty(v, level + 2)
                    inner_items.append(f"{key_str}: {val_str}")
                inner = ',\n'.join(' ' * (level + 2) + item for item in inner_items)
                return f'{obj.__class__.__name__}(\n' + inner + '\n' + prefix + ')'

            # Fallback: repr
            return repr(obj)

