        """
        Return a pretty formatted representation of self.
        """
        # Base indentation string
        base_indent = '    ' * max(0, indent)
        lines = [f"{base_indent}{self.__class__.__name__} ("]
        attrs = []
        # Collect attributes from __dict__ or via dir for slots
        try:
            if hasattr(self, "__dict__"):
                attrs = list(vars(self).items())
            else:
                for name in dir(self):
                    if name.startswith("_"):
