                        attrs.append((name, val))
                    except Exception:
                        continue
        except Exception:
            # Fallback to empty attrs
            attrs = []
        # Sort attributes by name for consistent order
        attrs.sort(key=lambda x: x[0])
        for name, value in attrs:
            # Indent attribute line
            attr_indent = '    ' * (indent + 1)
