def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise ValueError("Version must be a string")
    if version == "":
        raise ValueError("Empty version string is not allowed")
    if not version.isdigit():
        raise ValueError("Version must contain only digits")

    original_len = len(version)
    leading_zeros = len(version) - len(version.lstrip('0'))

    try:
        current_val = int(version)
    except ValueError:
        raise ValueError("Unable to parse version number")

    next_val = current_val + 1
    next_str = str(next_val)

    if leading_zeros > 0:
        # Preserve the original width by zero‑padding (zfill handles length grow).
        next_str = next_str.zfill(original_len)

    return next_str

