        # Preserve the original width by zero‑padding (zfill handles length grow).
        next_str = next_str.zfill(original_len)

    return next_str

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    if not version:
        raise ValueError("version string cannot be empty")
    if not version.isdigit():
        raise ValueError("version string must contain only digits")
    num = int(version)
    new_num = num + 1
    # Preserve leading zeros if the original version had them
    if version and version[0] == '0':
        width = len(version)
        return str(new_num).zfill(width)
    return str(new_num)

