def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).

    Returns True if all inventories are valid, otherwise raises an informative
    exception.
    """
    # This method assumes that `json` and `os` are available in the module
    # scope.  If they are not, they must be imported elsewhere in the code.
    cumulative_inventory = {}
    self.different_digests = {} if hasattr(self, "different_digests") else {}
    root_inventory = getattr(self, "root_inventory", None)

    for idx, dir_name in enumerate(version_dirs, start=1):
        inventory_path = os.path.join(dir_name, "inventory.json")
        if not os.path.isfile(inventory_path):
            raise FileNotFoundError(
                f"Inventory file missing for version directory '{dir_name}'. "
                f"Expected '{inventory_path}'."
            )
        try:
            with open(inventory_path, "r", encoding="utf-8") as f:
                inv = json.load(f)
        except json.JSONDecodeError as exc:
            raise ValueError(
                f"Invalid JSON in inventory '{inventory_path}': {exc}"
            ) from exc
        if not isinstance(inv, dict):
            raise ValueError(
                f"Inventory '{inventory_path}' is not a mapping of paths to digests."
            )

        # Verify that the inventory contains all entries present in previous versions
        missing_paths = [p for p in cumulative_inventory if p not in inv]
        if missing_paths:
            raise ValueError(
                f"Inventory in directory '{dir_name}' is missing entries from "
                f"previous versions: {missing_paths}"
            )

        # Update the cumulative inventory with the current version's entries
        cumulative_inventory.update(inv)

        # Compare digests with the root inventory, if available
        if isinstance(root_inventory, dict):
            for path, digest in inv.items():
                root_digest = root_inventory.get(path)
                if root_digest is not None and root_digest != digest:
                    # Store tuples of (root_digest, current_digest) for later reference
                    self.different_digests.setdefault(path, set()).add((root_digest, digest))

    return True

