def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    # Validate existence
    if not os.path.exists(path):
        return f'Path does not exist: {path}'

    try:
        # File case
        if os.path.isfile(path):
            return 'file'

        # Directory case
        if os.path.isdir(path):
            # Check for "0=*" files directly in this directory
            for entry in os.listdir(path):
                full = os.path.join(path, entry)
                if os.path.isfile(full) and entry.startswith('0='):
                    return 'object'

            # Check for subdirectories that contain "0=*" files (storage root)
            for entry in os.listdir(path):
                sub = os.path.join(path, entry)
                if os.path.isdir(sub):
                    try:
                        for subentry in os.listdir(sub):
                            subfull = os.path.join(sub, subentry)
                            if os.path.isfile(subfull) and subentry.startswith('0='):
                                return 'root'
                    except Exception:
                        continue

            return 'Unknown type'

        # If neither file nor dir
        return f'Unsupported path type: {path}'

    except Exception as exc:
        return f'Error inspecting path: {exc}'

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    # Basic existence and file/directory check
    try:
        if not os.path.exists(path):
            return "Path does not exist"
        if os.path.isfile(path):
            return "file"
        if not os.path.isdir(path):
            return "Not a file or directory"
    except Exception as exc:
        return f"Error accessing path: {exc}"

    # For directories, search for Namaste file(s) that start with "0="
    try:
        dir_entries = os.listdir(path)
    except Exception as exc:
        return f"Error listing directory: {exc}"

    namaste_files = [e for e in dir_entries if isinstance(e, str) and e.startswith("0=") and os.path.isfile(os.path.join(path, e))]
    if not namaste_files:
        return "No Namaste file found"

    # Heuristic based on presence of subdirectories typical for root vs object
    subdirs = set()
    for entry in dir_entries:
        full = os.path.join(path, entry)
        if os.path.isdir(full):
            subdirs.add(entry)
    # Typical OCFL root contains a subdirectory named "objects"
    if "objects" in subdirs:
        return "root"
    # Typical OCFL object contains a subdirectory named "versions"
    if "versions" in subdirs:
        return "object"

    # If heuristics fail, attempt to read the Namaste file content for clues
    namaste_path = os.path.join(path, namaste_files[0])
    try:
        with open(namaste_path, "r", encoding="utf-8", errors="ignore") as f:
            content = f.read().lower()
    except Exception:
        # Even if reading fails, we know there is a Namaste file, but type is ambiguous
        return "Namaste file present but cannot determine type"

    # Very simple content-based hints
    if "root:" in content or "ocfl_root:true" in content:
        return "root"
    if "object:" in content or "ocfl_object:true" in content:
        return "object"

    return "Cannot determine type from Namaste file"

