def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""

    # Basic validation for params
    if params is None:
        raise ValueError("params cannot be None")
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")

    # Normalize bug_ids into a list of ids
    ids_list = []
    if bug_ids is not None:
        if isinstance(bug_ids, (list, tuple, set)):
            ids_list = list(bug_ids)
        elif isinstance(bug_ids, str):
            # Treat commas as separators
            if "," in bug_ids:
                ids_list = [part.strip() for part in bug_ids.split(",") if part.strip()]
            else:
                ids_list = [bug_ids]
        else:  # single value (e.g., int)
            ids_list = [bug_ids]

    # If there are no ids to add, simply return the original params
    if not ids_list:
        return params

    # Merge with existing 'ids' key in params if present
    existing = params.get("ids")
    if existing is not None:
        if isinstance(existing, (list, tuple, set)):
            merged = list(existing) + ids_list
        else:
            merged = [existing] + ids_list
        # Remove duplicates while preserving order
        seen = set()
        merged_unique = []
        for x in merged:
            if x not in seen:
                seen.add(x)
                merged_unique.append(x)
        params["ids"] = merged_unique
    else:
        params["ids"] = ids_list

    return params

