    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Validate input
    if parser is None:
        raise TypeError("parser must not be None")
    # Retrieve actions; if attribute missing, treat as empty list
    actions = getattr(parser, "_actions", [])
    if not isinstance(actions, list):
        raise TypeError("parser does not have a valid _actions attribute")
    flags = []
    seen = set()
    for action in actions:
        option_strings = getattr(action, "option_strings", [])
        if not isinstance(option_strings, (list, tuple)):
            continue
        for opt in option_strings:
            if opt not in seen:
                flags.append(opt)
                seen.add(opt)
    return " ".join(flags)

