def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        raise TypeError(f"size must be a string, got {type(size).__name__}")
    val = size.strip()
    if not val:
        raise ValueError("size string is empty")

    import re

    # Pattern matches optional whitespace, numeric part (int or float), optional whitespace,
    # optional unit (K, MB, G, etc) ignoring case.
    pattern = r'^(?P<num>\d+(\.\d+)?)(?:\s*(?P<unit>[kKmMgGtTpPeE](?:b?)?))?$'
    m = re.fullmatch(pattern, val)
    if not m:
        raise ValueError(f"invalid size format: '{size}'")

    number_part = m.group("num")
    unit_part = m.group("unit")

    try:
        number = float(number_part)
    except ValueError:
        raise ValueError(f"cannot parse numeric value: '{number_part}'")

    # Determine multiplier based on unit
    if unit_part is None or unit_part == "":
        multiplier = 1
    else:
        u = unit_part.lower()
        if u.startswith("k"):
            multiplier = 10**3
        elif u.startswith("m"):
            multiplier = 10**6
        elif u.startswith("g"):
            multiplier = 10**9
        elif u.startswith("t"):
            multiplier = 10**12
        elif u.startswith("p"):
            multiplier = 10**15
        elif u.startswith("e"):
            multiplier = 10**18
        else:
            raise ValueError(f"unknown unit '{unit_part}' in size '{size}'")

    bytes_value = number * multiplier
    # Round to nearest integer since we're returning int
    return int(round(bytes_value))

