def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url_args:
        return url

    # Ensure url_args is a dictionary mapping
    try:
        if isinstance(url_args, dict):
            mapping = url_args
        else:
            mapping = dict(url_args)
    except Exception as exc:
        raise TypeError("url_args must be a dict or a mapping-like object") from exc

    try:
        return url.format(**mapping)
    except KeyError as exc:
        # A placeholder in the URL did not have a corresponding value
        missing = exc.args[0]
        raise ValueError(f"Missing value for URL placeholder '{missing}'") from None
    except Exception as exc:
        # Any other formatting error
        raise ValueError(f"Error formatting URL: {exc}") from exc

