def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Define common representations of a null/None value
    null_reprs = {"none", "null", "nan", "na", "n/a", ""}
    try:
        # If the value is actually None, consider it as None
        if val is None:
            return True
        # Handle bytes by decoding
        if isinstance(val, bytes):
            try:
                val = val.decode('utf-8', errors='ignore')
            except Exception:
                return False
        # Ensure we are working with a string-like object
        if not isinstance(val, str):
            return False
        # Normalize: strip whitespace and convert to lowercase
        stripped = val.strip().lower()
        return stripped in null_reprs
    except Exception:
        # Any unexpected error should not raise; return False
        return False

