def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Handle a missing parser gracefully
    if parser is None:
        return ''
    # The actions are stored in the private _actions attribute of ArgumentParser.
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("The provided object does not appear to be an argparse.ArgumentParser instance.")
    # Collect all option strings from each action (empty list for positional arguments).
    flags = []
    for action in actions:
        # action.option_strings is a list of the command-line flags (e.g. ['-f', '--foo']).
        flags.extend(action.option_strings)
    return ' '.join(flags)

