    """
    Convert a non-negative integer to a string representation using the provided alphabet.
    The most significant digit is placed first.
    """
    # Input validation
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError("alphabet must be a list or tuple of strings")
    if len(alphabet) == 0:
        raise ValueError("alphabet must contain at least one symbol")
    for idx, sym in enumerate(alphabet):
        if not isinstance(sym, str):
            raise TypeError(f"alphabet entry {idx} is not a string")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an integer or None")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    base = len(alphabet)

    # Special case: unary base (only one symbol)
    if base == 1:
        # Repeat the only symbol 'number' times; for 0, represent as one symbol
        if number == 0:
            result = alphabet[0]
        else:
            result = alphabet[0] * number
    else:
        # Standard base conversion
        digits = []
        n = number
        if n == 0:
            digits.append(alphabet[0])
        else:
            while n:
                digits.append(alphabet[n % base])
                n //= base
        result = ''.join(reversed(digits))

    # Apply optional left padding with the first symbol of the alphabet
    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return result

