    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    # Basic type checks
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    # Helper function to recursively replace values
    def _replace(obj):
        if isinstance(obj, dict):
            for key, val in obj.items():
                if val == register_value:
                    obj[key] = register_number
                else:
                    obj[key] = _replace(val)
        elif isinstance(obj, list):
            for i, item in enumerate(obj):
                if item == register_value:
                    obj[i] = register_number
                else:
                    obj[i] = _replace(item)
        elif isinstance(obj, tuple):
            # tuples are immutable; return a new tuple
            new_items = []
            for item in obj:
                if item == register_value:
                    new_items.append(register_number)
                else:
                    new_items.append(_replace(item))
            return tuple(new_items)
        elif isinstance(obj, set):
            # sets are mutable but contain hashable items; rebuild set
            new_set = set()
            for item in obj:
                if item == register_value:
                    new_set.add(register_number)
                else:
                    # items in set must remain hashable; if _replace returns non-hashable, we skip
                    try:
                        replaced = _replace(item)
                        new_set.add(replaced)
                    except Exception:
                        new_set.add(item)
            return new_set
        else:
            # for other types just return the object as is
            return obj
        return obj

    try:
