    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not string:
        raise ValueError("Input string must not be empty")

    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two symbols")

    # Handle optional leading minus sign for negative numbers
    negative = False
    if string[0] == '-':
        negative = True
        string = string[1:]
        if not string:
            raise ValueError("Input string cannot consist of only a minus sign")

    # Create a mapping from symbol to its numeric value for quick lookup
    mapping = {symbol: index for index, symbol in enumerate(alphabet)}

    value = 0
    for char in string:
        if char not in mapping:
            raise ValueError(f"Character '{char}' not found in the provided alphabet")
        value = value * base + mapping[char]

    return -value if negative else value

