def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Download a .tar.gz archive from the given URL and extract it to the specified destination_path.
    The archive is expected to contain package descriptor files for an Arch Linux repository.
    Returns the Path to the directory where the archive contents were extracted.

    Raises:
        RuntimeError: If there is a network error, download fails, or extraction fails.
    """
    # Ensure destination directory exists
    try:
        destination_path.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        raise RuntimeError(f"Failed to create destination directory '{destination_path}': {e}") from e

    # Download the archive to a temporary file
    tmp_file_path = None
    try:
        with requests.get(url, stream=True, timeout=30) as response:
            response.raise_for_status()
            # Use a temporary file to store the archive
            with tempfile.NamedTemporaryFile(delete=False, suffix=".tar.gz") as tmp_file:
                tmp_file_path = Path(tmp_file.name)
                for chunk in response.iter_content(chunk_size=8192):
                    if chunk:  # filter out keep-alive new chunks
                        tmp_file.write(chunk)
    except requests.RequestException as e:
        # Clean up temp file if it was created
        if tmp_file_path and tmp_file_path.exists():
            tmp_file_path.unlink()
        raise RuntimeError(f"Failed to download archive from '{url}': {e}") from e
    except Exception as e:
        if tmp_file_path and tmp_file_path.exists():
            tmp_file_path.unlink()
        raise RuntimeError(f"Unexpected error during download: {e}") from e

    # Extract the archive safely
    try:
        with tarfile.open(tmp_file_path, "r:gz") as tar:
            for member in tar.getmembers():
                # Skip external or unsafe paths (e.g., absolute or containing '..')
                member_path = destination_path / member.name
                try:
                    resolved_path = member_path.resolve(strict=False)
                except FileNotFoundError:
                    # If intermediate directories do not exist yet, resolve with parents
                    resolved_path = (destination_path.resolve(strict=False) / member.name).resolve()
                if not str(resolved_path).startswith(str(destination_path.resolve(strict=False))):
                    continue  # Skip potential path traversal
                tar.extract(member, path=destination_path)
    except (tarfile.TarError, Exception) as e:
        raise RuntimeError(f"Failed to extract archive '{tmp_file_path}': {e}") from e
    finally:
        # Clean up the temporary file
        try:
            if tmp_file_path and tmp_file_path.exists():
                tmp_file_path.unlink()
        except Exception:
            pass

    return destination_path

