def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """
    Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.
    This does not deal with the case where the archive passed along does not exist.
    """
    from pathlib import Path
    import shutil
    import tempfile
    import os
    import time

    # Resolve paths
    archive = Path(archive_path).expanduser().resolve()
    if not archive.is_file():
        raise FileNotFoundError(f"Archive does not exist: {archive_path}")

    tmp_dir = Path(tmp_path).expanduser().resolve()
    try:
        tmp_dir.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise RuntimeError(f"Could not ensure temporary directory '{tmp_dir}': {exc}")

    # Determine extraction directory
    if filename:
        # Sanitize filename for filesystem usage
        safe_name = "".join(c for c in filename if c.isalnum() or c in ("-", "_", ".")).rstrip()
        if not safe_name:
            safe_name = f"repo_{int(time.time())}"
        extract_dir = tmp_dir / f"{safe_name}_{int(time.time()*1000)}"
    else:
        extract_dir = Path(tempfile.mkdtemp(dir=tmp_dir))
    try:
        extract_dir.mkdir(parents=True, exist_ok=False)
    except FileExistsError:
        raise RuntimeError(f"Extraction directory already exists: {extract_dir}")

    # Unpack the archive
    try:
        shutil.unpack_archive(str(archive), str(extract_dir))
    except shutil.ReadError as err:
        # Cleanup extraction directory if unpack fails
        if extract_dir.exists():
            try:
                shutil.rmtree(extract_dir)
            except Exception:
                pass
        raise ValueError(f"Unable to unpack archive '{archive_path}': {err}")
    except Exception as exc:
        if extract_dir.exists():
            try:
                shutil.rmtree(extract_dir)
            except Exception:
                pass
        raise RuntimeError(f"Error unpacking archive '{archive_path}': {exc}")

    # Determine repository root:
    # If the archive extracted a single top-level directory, use that
    try:
        contents = [p for p in extract_dir.iterdir()]
    except Exception as exc:
        raise RuntimeError(f"Unable to list contents of extraction directory '{extract_dir}': {exc}")

    if len(contents) == 1 and contents[0].is_dir():
        repo_root = contents[0]
    else:
        repo_root = extract_dir

    # Return a file:// URL
    repo_root_abs = repo_root.absolute()
    file_url = f"file://{repo_root_abs}"
    return file_url

