def addignored(ignored):
    '''Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, and return those files as a single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            stderr=subprocess.STDOUT,
            text=True
        )
        # Split the output into a list of file names, filtering out empty lines
        files = [line.strip() for line in output.splitlines() if line.strip()]
        files.sort()
        return ','.join(files)
    except subprocess.CalledProcessError:
        # Git command failed (e.g., not a git repository); return empty string
        return ''
    except Exception:
        # Any other unexpected error; return empty string
        return ''

