def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Validate input type
    if not isinstance(host, (str, bytes)):
        return False
    # Convert bytes to string if necessary
    if isinstance(host, bytes):
        try:
            host = host.decode()
        except Exception:
            return False

    host = host.strip()
    if not host:
        return False

    # Common loopback aliases
    try:
        low = host.lower()
    except Exception:
        return False
    if low == "localhost":
        return True
    if host == "127.0.0.1":
        return True
    if host == "::1":
        return True

    # Attempt DNS resolution and check resolved addresses
    try:
        infos = socket.getaddrinfo(host, None, proto=socket.IPPROTO_TCP)
    except (socket.gaierror, socket.error, OSError):
        return False

