def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Only relevant on Windows
        if os.name != 'nt':
            return False
        # Git Bash sets OSTYPE to 'msys' (or similar)
        ostype = os.getenv('OSTYPE')
        if ostype and ostype.lower().startswith('msys'):
            return True
        # Git Bash also provides MSYSTEM variable (e.g., MINGW64)
        if os.getenv('MSYSTEM'):
            return True
        return False
    except Exception:
        # In any error case, default to False
        return False

