def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Normalize command and arguments
    if isinstance(commands, str):
        base_cmd = [commands]
    elif isinstance(commands, (list, tuple)):
        base_cmd = list(commands)
    else:
        raise TypeError(f"commands must be a str or list/tuple, got {type(commands).__name__}")

    if args is None:
        args = []
    elif not isinstance(args, (list, tuple)):
        raise TypeError(f"args must be a list or tuple, got {type(args).__name__}")

    cmd = base_cmd + list(args)

    if verbose:
        # Show the full command to be run
        import shlex
        print(f"Running command: {' '.join(shlex.quote(arg) for arg in cmd)}")

    stderr_target = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            text=True,
            check=False
        )
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {cmd[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Failed to run command {' '.join(cmd)}: {e}") from e

    if verbose:
        if result.stdout:
            print("Standard output:")
            print(result.stdout)
        # Only print stderr if it was captured and not hidden
        if not hide_stderr and result.stderr:
            print("Standard error:")
            print(result.stderr)

    return result

