    try:
        # If target is already an ipaddress object
        if isinstance(target, (ipaddress.IPv4Address, ipaddress.IPv6Address)):
            return isinstance(target, ipaddress.IPv4Address)

        # If target is a string representation of an IP address
        if isinstance(target, str):
            addr = ipaddress.ip_address(target.strip())
