        # If target is bytes/bytearray, attempt to parse directly
        if isinstance(target, (bytes, bytearray)):
            addr = ipaddress.ip_address(target)
            return isinstance(addr, ipaddress.IPv4Address)

        return False
    except (ValueError, TypeError):
        return False
    except Exception:
        # For any unexpected errors, fail safe by returning False
        return False

