def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    # If an explicit set of roots has been supplied, simply return it.
    if roots is not None:
        return set(roots)

    # If no graph is supplied, return an empty set.
    if graph is None:
        return set()

    try:
        # Collect all nodes that appear as subjects (children) and as objects (parents).
        subjects: Set["Node"] = set()
        objects:  Set["Node"] = set()

        # Iterate over all triples with the specified property.
        for child in graph.subjects(predicate=prop):
            subjects.add(child)
        for parent in graph.objects(predicate=prop):
            objects.add(parent)

        # Roots are those objects that never appear as a subject.
        roots_set: Set["Node"] = objects.difference(subjects)
        return roots_set
    except Exception as exc:
        # If something goes wrong (e.g., graph doesn't support the
        # traversal functions), fall back to an empty set.
        return set()

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """

    # Build a mapping from child -> list of parents following the given property.
    child_parents: Dict["Node", List["Node"]] = {}
    try:
        for child, _, parent in graph.triples((None, prop, None)):
            child_parents.setdefault(child, []).append(parent)
    except Exception:
        # If graph.triples fails, return empty set
        return set()

    # If the graph has no triples for the property, return empty set
    if not child_parents:
        return set()

    # Determine the set of nodes to start traversal from
    if roots is None:
        starting_nodes: Set["Node"] = set(child_parents.keys())
    else:
        # Ensure roots is a set and intersect with known children
        starting_nodes = set(roots) & set(child_parents.keys())

    # Traverse upward from each starting node to collect all ancestors
    all_ancestors: Set["Node"] = set()
    for start in starting_nodes:
        current = start
        # Use stack to avoid recursion
        stack: List["Node"] = [current]
        while stack:
            node = stack.pop()
            if node in all_ancestors:
                continue
            all_ancestors.add(node)
            for parent in child_parents.get(node, []):
                stack.append(parent)

    # Roots are nodes that have no parent within the collected ancestor set
    result_roots: Set["Node"] = set()
    for node in all_ancestors:
        parents = child_parents.get(node, [])
        if not parents:
            result_roots.add(node)
        else:
            # If none of the parents are in the ancestor set, node is a root
            if not any(parent in all_ancestors for parent in parents):
                result_roots.add(node)

    return result_roots

