def build_app_logger(name='app', logfile='app.log', debug=True):
    """
    General purpose application logger. Useful mainly for debugging
    """
    # Validate parameters
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if logfile is not None and not isinstance(logfile, str):
        raise TypeError("logfile must be a string or None")
    if not isinstance(debug, bool):
        raise TypeError("debug must be a boolean")

    # Get or create the logger
    logger = logging.getLogger(name)
    logger.setLevel(logging.DEBUG if debug else logging.INFO)

    # Define a formatter
    fmt = "%(asctime)s - %(name)s - %(levelname)s - %(message)s"
    formatter = logging.Formatter(fmt)

    # Avoid adding handlers multiple times
    def handler_exists(handler):
        if isinstance(handler, logging.FileHandler):
            return handler.baseFilename == os.path.abspath(logfile)
        if isinstance(handler, logging.StreamHandler):
            return handler.stream == sys.stdout
        return False

    if not any(handler_exists(h) for h in logger.handlers):
        # Stream handler (console output)
        try:
            stream_handler = logging.StreamHandler(sys.stdout)
            stream_handler.setLevel(logging.DEBUG if debug else logging.INFO)
            stream_handler.setFormatter(formatter)
            logger.addHandler(stream_handler)
        except Exception:
            # If we cannot attach a stream handler, ignore silently
            pass

        # File handler (if logfile specified)
        if logfile:
            try:
                # Ensure directory exists
                log_dir = os.path.dirname(os.path.abspath(logfile))
                if log_dir and not os.path.isdir(log_dir):
                    os.makedirs(log_dir, exist_ok=True)
                file_handler = logging.FileHandler(logfile, encoding='utf-8')
                file_handler.setLevel(logging.DEBUG if debug else logging.INFO)
                file_handler.setFormatter(formatter)
                logger.addHandler(file_handler)
            except Exception as e:
                # Log the exception to the stream handler if available, else re-raise
                if logger.handlers:
                    logger.error(f"Failed to create file handler for log '{logfile}': {e}")
                else:
                    # No handlers to log the error, re-raise to surface issue
                    raise

    # Prevent log propagation to root logger if not desired
    logger.propagate = False
    return logger

