def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple or int
        shape of the array to create
    dtype : `numpy.dtype` or equivalent
        data-type of the array to create
    """
    try:
        # Validate and normalize shape
        if isinstance(shape, int):
            shape_tuple = (int(shape),)
        elif isinstance(shape, (tuple, list)):
            shape_tuple = tuple(int(dim) for dim in shape)
        else:
            raise TypeError("shape must be an int, tuple, or list of integers")

        # Check for non-negative dimensions
        for dim in shape_tuple:
            if dim < 0:
                raise ValueError(f"Invalid dimension {dim}: dimensions must be non-negative")

        # Ensure dtype is a numpy.dtype
        if not isinstance(dtype, np.dtype):
            dtype = np.dtype(dtype)

        # Create the array (zero-initialized)
        array = np.zeros(shape_tuple, dtype=dtype)
        return array
    except Exception as e:
        raise ValueError(f"Unable to create array with shape {shape!r} and dtype {dtype!r}: {e}") from e

