def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
      - dict of configuration filename to corresponding parsed configuration
      - sequence of logging.LogRecord instances containing any parse errors
    Supports JSON and INI (.ini, .cfg, .conf) files. Unsupported extensions generate a warning.
    If `overrides` is provided, it should be a mapping from filename to a dict of key/value pairs
    that are merged into the parsed configuration after loading.
    If `resolve_env` is True, string values containing ${VAR} will be replaced by the
    corresponding environment variable value.
    """
    import json
    import configparser
    import io
    import logging
    import os
    import re

    if overrides is None:
        overrides = {}

    parsed_configs = {}
    log_records = []

    def _make_log_record(level, filename, msg, exc=None):
        return logging.LogRecord(
            name="load_configurations",
            level=level,
            pathname=filename,
            lineno=0,
            msg=msg,
            args=None,
            exc_info=exc,
        )

    def _resolve_env(value):
        if isinstance(value, str):
            # Replace ${VAR} with env var if present
            pattern = re.compile(r'\${([A-Za-z_][A-Za-z0-9_]*)}')
            def repl(m):
                return os.getenv(m.group(1), m.group(0))
            return pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: _resolve_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env(v) for v in value]
        else:
            return value

    for filename in config_filenames:
        try:
            with open(filename, "r", encoding="utf-8") as fp:
                raw_content = fp.read()
        except Exception as exc:
            log_records.append(_make_log_record(
                logging.ERROR, filename,
                f"Failed to read file '{filename}': {exc}", exc_info=exc))
            continue

        config = None
        # Detect file type by extension
        ext = os.path.splitext(filename)[1].lower()
        try:
            if ext == ".json":
                config = json.loads(raw_content)
                if not isinstance(config, dict):
                    raise ValueError("JSON root must be an object")
            elif ext in (".ini", ".cfg", ".conf"):
                parser = configparser.ConfigParser()
                parser.read_file(io.StringIO(raw_content))
                config = {section: dict(parser.items(section)) for section in parser.sections()}
            else:
                # Unsupported extension: create warning and skip
                log_records.append(_make_log_record(
                    logging.WARNING, filename,
                    f"Unsupported file extension '{ext}' for file '{filename}'. Skipping."))
                continue
        except Exception as exc:
            log_records.append(_make_log_record(
                logging.ERROR, filename,
                f"Failed to parse file '{filename}': {exc}", exc_info=exc))
            continue

        # Apply overrides for this file if provided
        if filename in overrides and isinstance(overrides[filename], dict):
            if isinstance(config, dict):
                # Merge top‑level keys; overrides overwrite
                config.update(overrides[filename])
            else:
                # Cannot apply overrides on non‑dict configs – skip silently
                pass

        # Resolve environment variables in string values
        if resolve_env:
            config = _resolve_env(config)

        parsed_configs[filename] = config

    return parsed_configs, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    json_mod = __import__('json')
    os_mod = __import__('os')
    re_mod = __import__('re')
    loaded_configs = {}
    error_records = []
    logger = logging.getLogger(__name__)

    env_pattern = re_mod.compile(r'\$\{([^}]+)\}')

    def _resolve(value):
        if isinstance(value, str):
            return env_pattern.sub(lambda m: os_mod.getenv(m.group(1), ''), value)
        if isinstance(value, list):
            return [_resolve(v) for v in value]
        if isinstance(value, dict):
            return {_resolve(k): _resolve(v) for k, v in value.items()}
        return value

    def _merge(base, overrides_dict):
        if not overrides_dict:
            return base
        merged = dict(base) if isinstance(base, dict) else base
        for key, override_val in overrides_dict.items():
            if isinstance(merged, dict) and isinstance(override_val, dict) and isinstance(merged.get(key), dict):
                merged[key] = _merge(merged.get(key, {}), override_val)
            else:
                merged[key] = override_val
        return merged

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as fp:
                cfg = json_mod.load(fp)
            if resolve_env:
                cfg = _resolve(cfg)
            if overrides:
                cfg = _merge(cfg, overrides)
            loaded_configs[fname] = cfg
        except FileNotFoundError as e:
            record = logging.LogRecord(logger.name, logging.ERROR, fname, 0,
                                       f"File not found: {fname}", None, exc_info=e)
            error_records.append(record)
        except json_mod.JSONDecodeError as e:
            record = logging.LogRecord(logger.name, logging.ERROR, fname, 0,
                                       f"JSON decode error in {fname}: {e.msg}", None, exc_info=e)
            error_records.append(record)
        except Exception as e:
            record = logging.LogRecord(logger.name, logging.ERROR, fname, 0,
                                       f"Unexpected error loading {fname}", None, exc_info=e)
            error_records.append(record)

    return loaded_configs, tuple(error_records)

