def scale(self, other=None):
    """
    Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Retrieve current scale attribute if it exists
    current_scale = getattr(self, "scale", None)

    # If other is None, just return the current scale
    if other is None:
        return current_scale

    # Validate that other is a numeric (int, float, Decimal, ... )
    try:
        new_scale = float(other)
    except Exception as exc:
        raise TypeError("Scale must be a numeric value") from exc

    # If current scale is unknown or zero, we cannot rescale
    if current_scale is None or current_scale == 0:
        # The custom exception is assumed to be defined elsewhere
        raise LenaValueError("Current scale is unknown or zero, cannot rescale")

    # Compute the scaling factor
    try:
        factor = new_scale / current_scale
    except Exception as exc:   # pragma: no cover – unlikely
        raise ValueError("Failed to compute scaling factor") from exc

    # -----------------------------------------------------------------
    # Rescale coordinate data.
    # The graph is assumed to store coordinate columns in `self.data`.
    # The last column corresponds to the coordinate to rescale.
    # -----------------------------------------------------------------
    if hasattr(self, "data"):
        # If data is a list/tuple of coordinate arrays (e.g. [x, y, z])
        if isinstance(self.data, (list, tuple)):
            try:
                last_coord = self.data[-1]
                # Support numpy array or python sequence
                if hasattr(last_coord, "shape") or isinstance(last_coord, (list, tuple)):
                    for i in range(len(last_coord)):
                        last_coord[i] *= factor
                else:
                    # Fallback – replace the whole array/list
                    self.data[-1] = last_coord * factor
            except Exception:     # pragma: no cover
                pass
        # If data is a 2D array with last column containing the target
        else:
            try:
                # Attempt numpy-style indexing if available
                if hasattr(self.data, "shape"):
                    self.data[..., -1] *= factor
                else:
                    # If it's a list of lists, scale last element of each sublist
                    for row in self.data:
                        if isinstance(row, (list, tuple)):
                            row[-1] *= factor
            except Exception:     # pragma: no cover
                pass

    # -----------------------------------------------------------------
    # Rescale error data, if present.
    # The assumption is that errors mirror the coordinate structure.
    # -----------------------------------------------------------------
    if hasattr(self, "errors"):
        if isinstance(self.errors, (list, tuple)):
            try:
                last_err = self.errors[-1]
                if hasattr(last_err, "shape") or isinstance(last_err, (list, tuple)):
                    for i in range(len(last_err)):
                        last_err[i] *= factor
                else:
                    self.errors[-1] = last_err * factor
            except Exception:     # pragma: no cover
                pass
