def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The function accepts datetime, date, Unix timestamp (int or float),
    or ISO‑8601 string and returns a UTC timestamp formatted as
    ``YYYY-mm-ddTHH:MM:SSZ``.  Naive datetimes are treated as UTC.
    """
    if dt is None:
        return None

    # Helper to format a datetime instance
    def _to_iso_utc(d):
        # make sure it is timezone aware (treat naive as UTC)
        if d.tzinfo is None:
            d = d.replace(tzinfo=datetime.timezone.utc)
        return d.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

    try:
        # datetime.datetime
        if isinstance(dt, datetime.datetime):
            return _to_iso_utc(dt)

        # datetime.date
        if isinstance(dt, datetime.date) and not isinstance(dt, datetime.datetime):
            # treat as midnight UTC
            return _to_iso_utc(datetime.datetime(dt.year, dt.month, dt.day,
                                                 tzinfo=datetime.timezone.utc))

        # Unix timestamp (int/float)
        if isinstance(dt, (int, float)):
            # assume seconds
            return _to_iso_utc(datetime.datetime.fromtimestamp(dt,
                                 tz=datetime.timezone.utc))

        # ISO‑8601 string
        if isinstance(dt, str):
            parsed = datetime.datetime.fromisoformat(dt)
            return _to_iso_utc(parsed)

    except Exception as exc:
        raise ValueError(f"Unable to format dt={dt!r}: {exc}") from exc

    raise TypeError(f"Unsupported type for dt: {type(dt).__name__}")

