def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET
    from typing import Dict, Any

    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict) and "entity_id" in data:
            # Return the parsed JSON as-is
            return data
    except Exception:
        pass

    # Fallback to XML parsing
    try:
        root = ET.fromstring(document)
    except ET.ParseError:
        raise ValueError("Document is not valid JSON or XML webfinger.") from None

    def _strip_ns(elem: ET.Element) -> None:
        """Recursively strip namespaces from an ElementTree element."""
        if '}' in elem.tag:
            elem.tag = elem.tag.split('}', 1)[1]
        for child in elem:
            _strip_ns(child)

    _strip_ns(root)

    # Extract subject
    subject_elem = root.find('Subject')
    subject = subject_elem.text.strip() if subject_elem is not None else None

    # Extract link elements
    links = []
    for link_elem in root.findall('Link'):
        # Gather all attributes
        attrs: Dict[str, str] = {k: v for k, v in link_elem.attrib.items()}
        # Also include any child text nodes if present (though usually links are empty)
        if link_elem.text and link_elem.text.strip():
            attrs['text'] = link_elem.text.strip()
        links.append(attrs)

    result: Dict[str, Any] = {}
    if subject:
        result['subject'] = subject
    if links:
        result['links'] = links
    if not result:
        # If nothing was found, return an empty dict
        result = {}

    return result

