def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    The function returns a dictionary representation of the webfinger data. 
    For JSON format it returns the parsed JSON. For XRD format it extracts
    the following fields into a dict:
        * subject   - string
        * aliases   - list of strings
        * properties - dict mapping property type to value
        * links     - list of dicts (each with 'rel', 'href', optional 'template')
    """
    if document is None or not isinstance(document, str) or document.strip() == "":
        raise ValueError("Input document must be a non-empty string")

    # Try JSON first
    try:
        import json
        parsed = json.loads(document)
        if isinstance(parsed, dict):
            return parsed
    except Exception:
        pass  # Not JSON, fall back to XRD parsing

    # Try XRD (XML) parsing
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
    except Exception as e:
        raise ValueError(f"Document is neither valid JSON nor XRD XML: {e}")

    # Namespace handling for XRD
    ns = {
        'x': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'
    }

    def _elem_text(elem):
        return elem.text.strip() if elem is not None and elem.text else None

    subject = _elem_text(root.find('x:Subject', ns))
    aliases = [_elem_text(a) for a in root.findall('x:Alias', ns) if _elem_text(a)]

    properties = {}
    for prop in root.findall('x:Property', ns):
        prop_type = prop.attrib.get('type')
        if prop_type:
            properties[prop_type] = _elem_text(prop) or ""

    links = []
    for link_elem in root.findall('x:Link', ns):
        link_dict = {}
        rel = link_elem.attrib.get('rel')
        if rel:
            link_dict['rel'] = rel
        href = link_elem.attrib.get('href')
        if href:
            link_dict['href'] = href
        tmpl = _elem_text(link_elem.find('x:Template', ns))
        if tmpl:
            link_dict['template'] = tmpl
        if link_dict:
            links.append(link_dict)

    result = {
        'subject': subject,
        'aliases': aliases,
        'properties': properties,
        'links': links
    }
    return result

