    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        raise ValueError("Document must be a non-empty string")

    document = document.strip()

    # Try JSON first
    if document.startswith('{') or document.startswith('['):
        import json
        try:
            data = json.loads(document)
        except Exception as err:
            raise ValueError(f"Invalid JSON webfinger document: {err}") from err
        return data

    # Assume XRD XML
    import xml.etree.ElementTree as ET
    try:
        root = ET.fromstring(document)
    except Exception as err:
        raise ValueError(f"Invalid XRD XML document: {err}") from err

    result: Dict = {}

    # Extract the subject
    subject_elem = root.find(
        ".//{http://xrd-info.org/ns}subject|.//{*}subject"
    )
    if subject_elem is not None:
        result["subject"] = subject_elem.text

    # Extract links
    links = []
    for link_elem in root.findall(".//{*}link"):
        href = link_elem.attrib.get("href")
        if href:
            links.append({
                "href": href,
                "rel": link_elem.attrib.get("rel"),
                "type": link_elem.attrib.get("type"),
            })
    if links:
        result["links"] = links

    # Extract title elements
    titles = [t.text for t in root.findall(".//{*}title") if t.text]
    if titles:
        result["titles"] = titles

    # If nothing useful was extracted, return raw content
    if not result:
        result["raw_xrd"] = document

    return result

