        * properties - dict mapping property type to value
        * links     - list of dicts (each with 'rel', 'href', optional 'template')
    """
    if document is None or not isinstance(document, str) or document.strip() == "":
        raise ValueError("Input document must be a non-empty string")

    # Try JSON first
    try:
        import json
        parsed = json.loads(document)
        if isinstance(parsed, dict):
            return parsed
    except Exception:
        pass  # Not JSON, fall back to XRD parsing

    # Try XRD (XML) parsing
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
    except Exception as e:
        raise ValueError(f"Document is neither valid JSON nor XRD XML: {e}")

    # Namespace handling for XRD
    ns = {
        'x': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'
    }

    def _elem_text(elem):
        return elem.text.strip() if elem is not None and elem.text else None

    subject = _elem_text(root.find('x:Subject', ns))
    aliases = [_elem_text(a) for a in root.findall('x:Alias', ns) if _elem_text(a)]

    properties = {}
    for prop in root.findall('x:Property', ns):
        prop_type = prop.attrib.get('type')
        if prop_type:
            properties[prop_type] = _elem_text(prop) or ""

    links = []
    for link_elem in root.findall('x:Link', ns):
        link_dict = {}
        rel = link_elem.attrib.get('rel')
        if rel:
            link_dict['rel'] = rel
        href = link_elem.attrib.get('href')
        if href:
            link_dict['href'] = href
        tmpl = _elem_text(link_elem.find('x:Template', ns))
        if tmpl:
            link_dict['template'] = tmpl
        if link_dict:
            links.append(link_dict)

    result = {
        'subject': subject,
        'aliases': aliases,
        'properties': properties,
        'links': links
    }
    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        raise ValueError("Document must be a non-empty string")

    document = document.strip()

    # Try JSON first
    if document.startswith('{') or document.startswith('['):
        import json
        try:
            data = json.loads(document)
        except Exception as err:
            raise ValueError(f"Invalid JSON webfinger document: {err}") from err
        return data

    # Assume XRD XML
    import xml.etree.ElementTree as ET
    try:
        root = ET.fromstring(document)
    except Exception as err:
        raise ValueError(f"Invalid XRD XML document: {err}") from err

    result: Dict = {}

    # Extract the subject
    subject_elem = root.find(
        ".//{http://xrd-info.org/ns}subject|.//{*}subject"
    )
    if subject_elem is not None:
        result["subject"] = subject_elem.text

    # Extract links
    links = []
    for link_elem in root.findall(".//{*}link"):
        href = link_elem.attrib.get("href")
        if href:
            links.append({
                "href": href,
                "rel": link_elem.attrib.get("rel"),
                "type": link_elem.attrib.get("type"),
            })
    if links:
        result["links"] = links

    # Extract title elements
    titles = [t.text for t in root.findall(".//{*}title") if t.text]
    if titles:
        result["titles"] = titles

    # If nothing useful was extracted, return raw content
    if not result:
        result["raw_xrd"] = document

    return result

