    netloc = parsed.netloc or parsed.path
    if not netloc:
        raise ValueError("Invalid host string provided")

    # Build the host‑meta URL
    url = f"{scheme}://{netloc}/.well-known/host-meta"

    # Helper function to perform the HTTP GET
    def _fetch(url_):
        with urllib.request.urlopen(url_, timeout=10) as resp:
            if resp.status != 200:
                raise ValueError(f"HTTP error {resp.status} retrieving host‑meta from {url_}")
            return resp.read()

    # Attempt to fetch the document, falling back to HTTP if HTTPS fails
    try:
        data = _fetch(url)
    except (urllib.error.HTTPError, urllib.error.URLError, ValueError) as err:
        if scheme == "https":
            # Retry with plain HTTP
            fallback_url = f"http://{netloc}/.well-known/host-meta"
            try:
                data = _fetch(fallback_url)
            except Exception as err2:
                raise ValueError(f"Failed to retrieve host‑meta: {err2}") from err2
        else:
            raise ValueError(f"Failed to retrieve host‑meta: {err}") from err

    # Parse the XML response into an ElementTree
    try:
        root = ET.fromstring(data)
    except ET.ParseError as err:
        raise ValueError(f"Failed to parse host‑meta XML: {err}") from err

    return root

