    Parameters
    ----------
    settings_dirs : Iterable[str] or str
        One or more directory paths to search for files. Non-existent or non‑directory paths are ignored.
    spec_option : str or None
        Defines the filtering rule for file names. If None or empty, all files are returned.
        If the string contains a wildcard (e.g., '*.ini'), a glob pattern match is performed.
        Otherwise, the string is treated as one or more file extensions separated by commas
        (case‑insensitive, with or without a leading dot).

    Returns
    -------
    List[str]
        A sorted list of absolute file paths that satisfy the given criteria.
    """
    # Normalise settings_dirs to a list of strings
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except Exception:
            # If conversion fails, treat as empty list
            dirs = []

    # Prepare extension or glob patterns
    def _prepare_filters(option):
        if not option or not isinstance(option, str):
            return None, None
        option = option.strip()
        if not option:
            return None, None
        if '*' in option or '?' in option or '[' in option:
            return None, option  # glob pattern
        # Assume comma‑separated extensions
        exts = [e.strip().lower().lstrip('.')
                for e in option.split(',')
                if e.strip()]
        exts = list(set(exts))  # deduplicate
        return exts, None

    extensions, glob_pattern = _prepare_filters(spec_option)

    matched = []

    # Import needed modules (local imports to avoid top‑level imports)
    try:
        import os
        import fnmatch
    except Exception:
        # If modules are unavailable, return empty list
        return []

    for dir_path in dirs:
        if not isinstance(dir_path, str) or not dir_path:
            continue
        try:
            if not os.path.isdir(dir_path):
                continue
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if not os.path.isfile(full_path):
                    continue
                filename_lower = entry.lower()
                # Filter by glob pattern if provided
                if glob_pattern:
                    if fnmatch.fnmatch(filename_lower, glob_pattern.lower()):
                        matched.append(os.path.abspath(full_path))
                    continue
                # Filter by extensions
                if extensions:
                    ext = os.path.splitext(filename_lower)[1].lstrip('.')
                    if ext in extensions:
