@classmethod
def ansible_config_manager(cls):
    """Gets the ansible config manager."""
    try:
        import os
        import configparser

        # Determine the path to the ansible config file
        cfg_path = os.getenv("ANSIBLE_CFG", "ansible.cfg")
        if not os.path.isabs(cfg_path):
            cfg_path = os.path.join(os.getcwd(), cfg_path)

        # If the config file doesn't exist, return an empty dict
        if not os.path.isfile(cfg_path):
            return {}

        # Load and parse the configuration file
        parser = configparser.ConfigParser()
        parser.read(cfg_path)

        # Return the parser object for direct use or convert to dict if preferred
        return parser
    except Exception as exc:
        # Wrap any exception in a more informative RuntimeError
        raise RuntimeError(f"Could not load Ansible configuration: {exc}") from exc

