    """Resolves the include dict directive in the spec files."""
    def _merge_dicts(target, source):
        """Recursively merge source into target."""
        for key, value in source.items():
            if key in target:
                # If both values are dicts, merge recursively
                if isinstance(target[key], dict) and isinstance(value, dict):
                    _merge_dicts(target[key], value)
                else:
                    # Otherwise overwrite
                    target[key] = value
            else:
                target[key] = value

    def _resolve(include_obj, parent):
        """
        Resolve a single include entry (dict or list of dicts) into the parent dict.
        """
        if isinstance(include_obj, dict):
            _merge_dicts(parent, include_obj)
        elif isinstance(include_obj, list):
            for item in include_obj:
                _resolve(item, parent)
        else:
            # Unsupported type; skip or raise an error
            raise TypeError(f"Unsupported include type: {type(include_obj).__name__}")

