def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        # Ensure we have dictionaries to work with
        if cli_args is None:
            cli_args = {}
        if answer_file_args is None:
            answer_file_args = {}

        if not isinstance(cli_args, dict):
            raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
        if not isinstance(answer_file_args, dict):
            raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

        # The set of deprecated arguments is expected to be stored in the instance.
        # If it's not present, we simply do nothing.
        deprecated = getattr(self, "deprecated_args", set())

        # Helper to format deprecation messages
        def _print_deprecation(arg_name, source):
            message = f"WARNING: Argument '{arg_name}' is deprecated and comes from {source}."
            # In a real application, you might use logging.warn instead of print
            print(message)

        # Check CLI arguments
        for arg, value in cli_args.items():
            if arg in deprecated and value is not None:
                _print_deprecation(arg, "CLI")

        # Check answer file arguments
        for arg, value in answer_file_args.items():
            if arg in deprecated and value is not None:
                _print_deprecation(arg, "Answer file")

        # If the same deprecated argument appears in both sources, inform the user
        common_deprecated = set(cli_args) & set(answer_file_args) & deprecated
        for arg in common_deprecated:
            msg = (
                f"NOTICE: Deprecated argument '{arg}' provided both via CLI and answer file. "
                f"The CLI value will take precedence."
            )
            print(msg)

