        """list of silenced argument

        :param args: The received arguments.
        :return: list, silenced argument names
        """
        # Handle None input
        if args is None:
            return []

        silent = set()

        # Helper closure to decide if a value should be considered silent
        def is_silent(val):
            # Consider None, empty containers, empty string, and False as silent
            if val is None:
                return True
            if isinstance(val, bool):
                return not val
            if isinstance(val, (str, bytes)):
                return val == ''
            if isinstance(val, (list, tuple, set, dict)):
                return len(val) == 0
            # Numeric zero can be ambiguous; treat as silent only if explicitly zero
            if isinstance(val, (int, float)):
                # Treat 0.0 and 0 as silent only if context-specific; here we skip
                return False
            return False

        # If args is a mapping-like object
        if isinstance(args, dict) or hasattr(args, '__dict__') and isinstance(vars(args), dict):
            if isinstance(args, dict):
                items = args.items()
            else:
                items = vars(args).items()
            for key, value in items:
                try:
                    if is_silent(value):
                        silent.add(key)
                except Exception:
                    # If we can't evaluate, skip this entry
                    continue

        # If args is an iterable of (key, value) pairs
        elif hasattr(args, '__iter__'):
            for item in args:
                try:
                    if isinstance(item, (tuple, list)) and len(item) == 2:
                        key, value = item
                        if is_silent(value):
                            silent.add(str(key))
                except Exception:
                    continue

        # If args is a simple object without dict, inspect attributes
        else:
            for attr in dir(args):
                if attr.startswith('_'):
                    continue
                try:
                    value = getattr(args, attr)
                    if is_silent(value):
                        silent.add(attr)
                except Exception:
                    continue

        # Return sorted list for deterministic order
        return sorted(silent)

