    if args is None:
        raise TypeError("args cannot be None")

    # Retrieve optional min and max bounds from the instance
    min_val = getattr(self, "min", None)
    max_val = getattr(self, "max", None)

    # If min is greater than max, raise an error as that is an invalid configuration
    if min_val is not None and max_val is not None and min_val > max_val:
        raise ValueError(f"Inconsistent bounds: min ({min_val}) > max ({max_val})")

    # Normalize ``args`` into an iterable of values
    if isinstance(args, dict):
        iterable = args.values()
    elif isinstance(args, (list, tuple, set, frozenset)):
        iterable = args
    else:
