    :raises TypeError: If `args` is not a dictionary or if a value is not numeric.
    :raises ValueError: If any value is outside the supplied bounds.
    :returns: True if all values satisfy their bounds.
    """
    if not isinstance(args, dict):
        raise TypeError("`args` must be a dictionary")

    def _validate(name, value, min_val=None, max_val=None):
        if not isinstance(value, (int, float)):
            raise TypeError(f"Argument '{name}' must be numeric; got {type(value).__name__}")
        if min_val is not None:
            if not isinstance(min_val, (int, float)):
                raise TypeError(f"Minimum bound for '{name}' must be numeric; got {type(min_val).__name__}")
            if value < min_val:
