def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    try:
        # Validate inputs
        if not isinstance(subcommand, str):
            raise TypeError(
                f"'subcommand' must be a string, got {type(subcommand).__name__}"
            )
        if not isinstance(type_name, str):
            raise TypeError(
                f"'type_name' must be a string, got {type(type_name).__name__}"
            )
        if not isinstance(option_name, str):
            raise TypeError(
                f"'option_name' must be a string, got {type(option_name).__name__}"
            )
        if spec_option is None:
            spec_option = {}
        elif not isinstance(spec_option, dict):
            raise TypeError(
                f"'spec_option' must be a dict, got {type(spec_option).__name__}"
            )

        # Build attributes for the complex type
        attrs = {
            "subcommand": subcommand,
            "type_name": type_name,
            "option_name": option_name,
        }
        # Merge any additional spec keys
        attrs.update(spec_option)

        # Use SimpleNamespace for a lightweight attribute holder
        import types

        return types.SimpleNamespace(**attrs)

    except Exception as exc:
        # Provide a clear error message for debugging
        raise ValueError(
            f"Failed to create complex argument type for subcommand='{subcommand}', "
            f"type_name='{type_name}', option_name='{option_name}': {exc}"
        ) from exc

