    # Basic validation of inputs
    if not isinstance(playbook_path, str) or not playbook_path:
        raise ValueError("playbook_path must be a non-empty string")

    # Start building the command
    cmd = ["ansible-playbook", playbook_path]

    # Handle verbosity
    if verbose is not None:
        try:
            v = int(verbose)
            if v < 0:
                raise ValueError
        except Exception:
            raise ValueError("verbose must be a non‑negative integer")
        if v > 0:
            # Ansible accepts -v, -vv, -vvv; construct accordingly
            cmd.append("-" + "v" * v)

    # Handle extra vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise ValueError("extra_vars must be a dictionary")
        # Convert dict to JSON string and pass via -e
        try:
            extra_json = json.dumps(extra_vars, separators=(",", ":"))
        except Exception as e:
            raise ValueError(f"Could not serialize extra_vars: {e}")
        cmd.extend(["-e", extra_json])

    # Handle ansible_args
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise ValueError("ansible_args must be a dictionary")
        for key, value in ansible_args.items():
            if value is None:
                continue
            flag = f"--{key}" if not key.startswith("--") else key
            if isinstance(value, bool):
                if value:
                    # True means include the flag without value
                    cmd.append(flag)
                else:
                    # False means skip the flag
                    continue
            elif isinstance(value, (list, tuple)):
                # Join list items with space; each considered part of argument
                for part in value:
                    cmd.append(flag)
                    cmd.append(str(part))
            else:
                cmd.append(flag)
                cmd.append(str(value))

    # Log the command (assuming the plugin has a logger with debug)
    try:
        logger = ir_plugin.get_logger()
    except Exception:
        logger = None
    if logger:
        logger.debug(f"Running ansible command: {' '.join(cmd)}")

    # Execute command
    try:
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.path if hasattr(ir_workspace, "path") else None,
            text=True,
            capture_output=True,
            check=False,
        )
    except FileNotFoundError:
        raise RuntimeError("ansible-playbook command not found. Is Ansible installed?")
    except Exception as exc:
        raise RuntimeError(f"Failed to run ansible-playbook: {exc}")

    # Log output if logger is present
    if logger:
        if result.stdout:
            logger.info(f"ansible-playbook stdout:\n{result.stdout}")
        if result.stderr:
            logger.warning(f"ansible-playbook stderr:\n{result.stderr}")

    # Raise if failed
    if result.returncode != 0:
        raise RuntimeError(
            f"ansible-playbook exited with code {result.returncode}. "
            f"Check logs or stderr for details."
        )

    return result

