def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    # Validate plugin_dir
    if not isinstance(plugin_dir, (str, os.PathLike)):
        raise TypeError(f"plugin_dir must be a string or path-like object, got {type(plugin_dir).__name__}")
    plugin_dir = os.fspath(plugin_dir)
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Plugin directory '{plugin_dir}' does not exist or is not a directory.")

    # Search for a spec file. Prefer JSON, but allow YAML if yaml library is available
    def _find_spec_file():
        candidates = ["plugin.json", "plugin.yaml", "plugin.yml"]
        for name in candidates:
            path = os.path.join(plugin_dir, name)
            if os.path.isfile(path):
                return path
        # If nothing found, look for any .json or .yaml/.yml file
        for fname in os.listdir(plugin_dir):
            fpath = os.path.join(plugin_dir, fname)
            if os.path.isfile(fpath) and fname.lower().endswith((".json", ".yaml", ".yml")):
                return fpath
        return None

    spec_path = _find_spec_file()
    if not spec_path:
        raise FileNotFoundError(f"No plugin spec file (.json or .yaml/.yml) found in '{plugin_dir}'.")

    # Load spec content
    try:
        if spec_path.lower().endswith(".json"):
            with open(spec_path, "r", encoding="utf-8") as f:
                data = json.load(f)
        else:
            # YAML support
            try:
                import yaml
            except ImportError as exc:
                raise ImportError("YAML file found but PyYAML is not installed.") from exc
            with open(spec_path, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
    except Exception as exc:
        raise ValueError(f"Failed to load plugin spec from '{spec_path}': {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError(f"Plugin spec must be a dictionary at the top level, got {type(data).__name__}")

    # Flatten to dot notation
    def _flatten(d, parent_key=""):
        flat = {}
        for k, v in d.items():
            if not isinstance(k, str):
                raise ValueError(f"All keys in plugin spec must be strings, found key of type {type(k).__name__}")
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, new_key))
            else:
                flat[new_key] = v
        return flat

    return _flatten(data)

