def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")

    # Normalize path separators to '/' for consistency (handles Windows paths)
    path_norm = path.replace("\\", "/")
    root_norm = root.replace("\\", "/")

    # Strip any trailing slashes (except for root being the root directory alone)
    def _strip_trailing_slash(p):
        if p != "/" and p.endswith("/"):
            return p.rstrip("/")
        return p

    path_norm = _strip_trailing_slash(path_norm)
    root_norm = _strip_trailing_slash(root_norm)

    if not path_norm or not root_norm:
        raise ValueError("path and root must not be empty")

    # If the root and path are exactly the same, return an empty string
    if path_norm == root_norm:
        return ""

    # Ensure root is a prefix of path with a directory separator boundary
    prefix = root_norm + "/"
    if path_norm.startswith(prefix):
        return path_norm[len(prefix):]

    # If not a prefix, raise an exception
    raise ValueError(f"Root '{root}' is not a prefix of the given path '{path}'")

